// ==UserScript==
// @name         惨剧轮回 — 彩窗书卷界面
// @namespace    local.lacrima-interface
// @version      3.2.5
// @description  Illuminated open-book UI mod with editable titles. Uses the original page's images and controls.
// @match        https://tragic-aiplay.cn/auto_play.html*
// @run-at       document-idle
// @grant        none
// ==/UserScript==
(() => { const style = document.createElement('style'); style.textContent = "/* Presentation-only mod. Original artwork, game nodes and handlers remain owned by the game. */\n/* Chrome resolves this installed OTF by its PostScript name, not its Windows family label. */\n@font-face{font-family:\"Loop Tsukushi\";src:local(\"TsukuMinPro-L\");font-style:normal;font-weight:400;font-display:swap}\n.loop-intro,.loop-header-actions,.loop-panel-glass,.loop-ambient,.loop-book-margins{display:none}\n.loop-settings:not([open]),.loop-restore[hidden]{display:none!important}\nbody.loop-ui{\n  --loop-ink:#332e2c;--loop-muted:#6a6057;--loop-rubric:#743c4d;\n  --loop-gold:#ad8b52;--loop-paper:#f4eddd;--loop-paper-raised:#fcf7ed;\n  --loop-rule:#d8ccba;--loop-control:#ad9d89;\n  --loop-glass-blue:#325f68;--loop-glass-blue-soft:#e3eeeb;\n  --loop-glass-teal:#345e52;--loop-glass-rose:#f0e2e4;\n  --loop-night:#1b171b;--loop-night-raised:#292328;--loop-night-ink:#eee3cf;--loop-night-muted:#c5b8a8;\n  --loop-body-font:\"Loop Tsukushi\",\"FOT-TsukuMin Pro L\",\"Tsukushi Mincho\",\"筑紫明朝\",\"Yu Mincho\",\"Noto Serif SC\",\"Noto Serif CJK SC\",\"SimSun\",serif;\n  /* Native dark dialogs inherit dark tokens; paper regions override them locally below. */\n  --ink:var(--loop-night-ink);--text:var(--loop-night-ink);--muted:var(--loop-night-muted);\n  --panel:var(--loop-night-raised);--line:#645653;--accent:#d4bf93;--accent-soft:#3c3431;\n  margin:0;background:var(--loop-night);color:var(--loop-night-ink);\n  font:14px/1.65 var(--loop-body-font);font-kerning:normal;\n}\n.loop-ui :is(button,input,select,textarea){font-family:var(--loop-body-font);font-kerning:normal}\n.loop-ui :is(button,a,input,textarea,select,[tabindex]):focus-visible{outline:2px solid var(--loop-glass-blue);outline-offset:3px}\n.loop-ui :is(.side-panel,.report-panel,.play-area,.loop-settings){\n  --ink:var(--loop-ink);--text:var(--loop-ink);--muted:var(--loop-muted);\n  --accent:var(--loop-glass-blue);--accent-soft:var(--loop-glass-blue-soft);\n  --panel:var(--loop-paper-raised);--line:var(--loop-rule);--shadow:none;\n  color:var(--loop-ink);color-scheme:light;\n}\n.loop-ui ::selection{background:#d8c3cb;color:#38242c}\n.loop-ui .loop-ambient{display:flex;position:fixed;inset:0;justify-content:space-between;pointer-events:none;overflow:hidden;z-index:-1;opacity:.2}\n.loop-ambient>div{width:220px;height:70vh;margin:105px -110px 0}\n.loop-ambient svg{width:100%;height:100%}\n/* The compact toolbar and margin title leave the actual map as the dominant object. */\n.loop-ui>header{position:relative!important;inset:auto!important;display:flex;align-items:center;flex-wrap:wrap;gap:12px 24px;padding:10px 24px!important;min-height:52px;height:auto;background:var(--loop-night)!important;border:0!important;box-shadow:none!important}\n.loop-ui>header>.header-title{display:none!important}\n.loop-ui>header>.toolbar{display:flex;margin:0;flex-wrap:wrap;gap:18px}\n.loop-ui>header .nav{font:13px/1.5 var(--loop-body-font);color:var(--loop-night-muted);letter-spacing:0;text-decoration:none;min-height:32px;display:inline-flex;align-items:center}\n.loop-ui>header .nav:hover{color:#fff4de}\n.loop-ui>header #musicPlayer{margin-left:auto;max-width:100%;color:var(--loop-night-muted);font-size:12px}\n.loop-ui>header #musicPlayer button{color:var(--loop-night-ink);background:transparent;border:1px solid #645653;border-radius:2px;min-width:32px;min-height:32px}\n.loop-ui>header :is(button,a):focus-visible{outline-color:#e1c591}\n.loop-ui>header button:disabled{color:#ae9f92;opacity:1;cursor:not-allowed}\n.loop-ui .loop-header-actions{display:flex;gap:8px;margin-left:auto;align-items:center}\n.loop-ui .loop-header-actions button,.loop-ui .loop-intro button{color:var(--loop-night-ink);background:transparent;border:1px solid #776453;border-radius:2px;box-shadow:none;padding:7px 12px;min-height:34px;font-size:12px;letter-spacing:.04em;cursor:pointer}\n.loop-ui .loop-header-actions button:hover,.loop-ui .loop-intro button:hover{background:#362b30;border-color:#c1a16b}\n.loop-ui .loop-intro{position:relative;display:flex;align-items:center;gap:16px;max-width:1920px;box-sizing:border-box;margin:auto;padding:18px 24px 24px;min-height:96px}\n.loop-title-ornament{width:48px;height:48px;flex:0 0 48px}\n.loop-title-ornament svg{width:100%;height:100%}\n.loop-intro-copy{min-width:0;text-align:left}\n.loop-ui .loop-intro h1{font:400 28px/1.45 var(--loop-title-font);letter-spacing:.09em;color:var(--loop-night-ink);margin:0;overflow-wrap:anywhere;text-wrap:balance}\n.loop-ui .loop-intro p{font:13px/1.8 var(--loop-body-font);letter-spacing:.04em;color:var(--loop-night-muted);margin:4px 0 0;white-space:pre-line;overflow-wrap:anywhere}\n.loop-intro p[hidden]{display:none}\n.loop-intro-actions{margin-left:auto;flex:0 0 auto}\n.loop-ui>main{max-width:1920px;margin:auto;gap:20px;align-items:start}\n/* 1440 desktop = 2*24 outer + 224 control + 848 book + 280 reports + 2*20 gutters. */\n.loop-ui .play-area{min-width:0;position:relative;padding:20px 24px 34px;gap:20px;border:1px solid #a58b61;border-radius:3px;\n  /* One physical fold: the only shaded surface, required by the open Bible brief. */\n  background:linear-gradient(90deg,transparent calc(var(--loop-spine,50%) - 32px),#9a805b20 calc(var(--loop-spine,50%) - 12px),#80634266 var(--loop-spine,50%),#9a805b20 calc(var(--loop-spine,50%) + 10px),transparent calc(var(--loop-spine,50%) + 32px)),var(--loop-paper); /* taste-skill-ignore: physical book fold explicitly requested by user */\n  box-shadow:0 3px 0 #d6c6a4,0 4px 0 #8a7454,0 7px 0 #e3d6ba,0 8px 0 #8a7454,0 12px 0 2px #453039,0 13px 0 3px #987747; /* taste-skill-ignore: physical page layers, not a floating dashboard panel */\n  animation:loop-open-book .45s ease-out both;\n}\n.loop-ui .play-area::before{content:\"\";position:absolute;inset:8px;pointer-events:none;border:1px solid #b79c6b55;border-radius:2px}\n.loop-ui .play-area::after{content:\"\";position:absolute;bottom:8px;left:calc(var(--loop-spine,50%) - 3px);width:6px;height:6px;border:1px solid #795d39;transform:rotate(45deg);pointer-events:none}\n.loop-ui .loop-book-margins{display:block;position:absolute;inset:2px;pointer-events:none;z-index:2}\n.loop-book-margins i{position:absolute;width:42px;height:42px;opacity:.8}\n.loop-book-margins svg{width:100%;height:100%}\n.loop-book-margins i:nth-child(1){top:0;left:0}\n.loop-book-margins i:nth-child(2){top:0;right:0;transform:scaleX(-1)}\n.loop-book-margins i:nth-child(3){bottom:0;left:0;transform:scaleY(-1)}\n.loop-book-margins i:nth-child(4){bottom:0;right:0;transform:scale(-1)}\n.loop-book-margins b{position:absolute;top:-3px;left:calc(var(--loop-spine,50%) - 8px);width:14px;height:24px;background:var(--loop-rubric);border:1px solid #9d704e;clip-path:polygon(0 0,100% 0,100% 100%,50% 80%,0 100%)}\n.loop-ui .board-section{padding:0;background:transparent;border:0;border-radius:0;box-shadow:none;min-width:0}\n.loop-ui .board-section>.row h2{color:var(--loop-rubric);font:400 16px/1.5 var(--loop-title-font);letter-spacing:.1em}\n.loop-ui .phase-banner{--ink:var(--loop-night-ink);--text:var(--loop-night-ink);--muted:var(--loop-night-muted);border-color:#7b6657;background:#30262e;color:var(--loop-night-ink);box-shadow:none;border-radius:2px;margin:0 0 18px;min-height:44px}\n.loop-ui .phase-banner.hot{border-color:var(--loop-rubric);background:var(--loop-glass-rose);color:#562c3a;box-shadow:none}\n.loop-ui .phase-main>.phase-pin{width:24px;height:24px;flex:0 0 auto}\n.loop-ui .phase-main>strong{font-family:var(--loop-body-font);font-weight:400;font-size:14px;line-height:1.6}\n.loop-ui .phase-banner-right>.phase-today-incident{font-size:12px;color:inherit}\n.loop-ui .phase-banner:not([class*=\"has-\"]) .phase-main{flex:1;min-width:0}\n.loop-ui .board-counter-toggle{background:transparent;color:inherit;border-color:#948574;border-radius:2px;box-shadow:none}\n.loop-ui #board{gap:18px}\n.loop-ui #board>.location{border:1px solid #8c7149;border-radius:1px;box-shadow:none;outline-offset:4px}\n/* No overlay on the artwork: only the original images occupy the map windows. */\n.loop-ui #handPanel{--ink:var(--loop-night-ink);--text:var(--loop-night-ink);--muted:var(--loop-night-muted);--panel:#292328;--line:#655650;--accent:#dac395;--accent-soft:#41372f;border:1px solid #826b53;border-radius:2px;background:#292328;color:var(--loop-night-ink);box-shadow:none;padding:14px;animation:none}\n.loop-ui #handPanel h2{color:var(--loop-night-ink);font-size:14px;font-weight:400;letter-spacing:.05em}\n.loop-ui #handPanel .status{color:var(--loop-night-muted)}\n.loop-ui #handPanel :is(button,.seat-label){font-family:var(--loop-body-font)}\n.loop-ui #handPanel button{background:#342c30;border-color:#827160;color:var(--loop-night-ink);border-radius:2px;box-shadow:none}\n.loop-ui #handPanel button:hover:enabled{background:#4b3b42;border-color:#c4a56d}\n.loop-ui #handPanel button:disabled{background:transparent;color:#baac9c;opacity:1;cursor:not-allowed}\n.loop-ui #handPanel :is(button,[tabindex]):focus-visible{outline-color:#e1c591}\n.loop-ui .action-card.selected{outline:2px solid #e1c591;outline-offset:3px;box-shadow:none}\n.loop-ui .action-card small{font-size:11px;line-height:1.5}\n.loop-ui .side-panel,.loop-ui .report-panel{font-size:14px;line-height:1.75;gap:0;background:var(--loop-paper);border:1px solid #c5b699;border-radius:2px;box-shadow:none;scrollbar-color:#a59986 transparent;scrollbar-width:thin}\n.loop-ui :is(.side-panel,.report-panel)>section{background:transparent;color:var(--loop-ink);box-shadow:none;border:0;border-bottom:1px solid var(--loop-rule);border-radius:0;padding:16px;min-width:0}\n.loop-ui :is(.side-panel,.report-panel)>section:last-child{border-bottom:0}\n.loop-ui :is(.side-panel,.report-panel) h2{color:var(--loop-rubric);font:400 16px/1.5 var(--loop-title-font);letter-spacing:.08em}\n.loop-ui :is(.side-panel,.report-panel) h3{color:var(--loop-ink);font:400 14px/1.7 var(--loop-body-font)}\n.loop-ui :is(.side-panel,.report-panel) .status{color:var(--loop-muted);font:13px/1.75 var(--loop-body-font)}\n.loop-ui .side-panel>section:first-of-type{position:relative;padding-top:20px}\n.loop-ui .loop-panel-glass{display:block;position:absolute;right:8px;top:8px;width:52px;height:52px;opacity:.08;pointer-events:none}\n.loop-panel-glass svg{width:100%;height:100%}\n.loop-ui .side-panel>section:first-of-type>:not(.loop-panel-glass){position:relative;z-index:1}\n/* Light controls use explicit ink; never inherit the live site's white-on-blue theme. */\n.loop-ui :is(.side-panel,.report-panel) :is(button,input,textarea,select){background:var(--loop-paper-raised);color:var(--loop-ink);border:1px solid var(--loop-control);border-radius:2px;box-shadow:none;font-weight:400;accent-color:var(--loop-glass-blue)}\n.loop-ui :is(.side-panel,.report-panel) button{min-height:32px;padding:5px 9px;font-size:12px;line-height:1.5;cursor:pointer}\n.loop-ui :is(.side-panel,.report-panel) button:hover:enabled{background:var(--loop-glass-blue-soft);border-color:var(--loop-glass-blue);color:#234b52}\n.loop-ui :is(.side-panel,.report-panel) button:disabled{background:#e8e0d2;color:#71685e;opacity:1;cursor:not-allowed}\n.loop-ui :is(.side-panel,.report-panel) :is(a,.tiny-link-button){color:var(--loop-glass-blue)}\n.loop-ui :is(.side-panel,.report-panel) a:hover{text-decoration:underline;text-underline-offset:3px}\n.loop-ui .side-panel .match-session-actions{grid-template-columns:minmax(0,1fr) 58px}\n.loop-ui .side-panel .match-session-actions button{padding:8px 5px;font-size:12px}\n.loop-ui .side-panel .start-match-button{flex-wrap:wrap}\n.loop-ui .side-panel #startButton{background:var(--loop-rubric);border-color:var(--loop-rubric);color:#fff6e8}\n.loop-ui .side-panel #startButton small{color:#f1dfe3}\n.loop-ui .side-panel #startButton:hover:enabled{background:#5b2f3d;color:#fff6e8}\n.loop-ui .side-panel #surrenderTopButton{color:#793747;background:transparent}\n.loop-ui .side-panel>.sidebar-utility-button{margin:10px 16px;width:calc(100% - 32px);background:transparent}\n.loop-ui #actionPanel{border-left:2px solid var(--loop-rule)}\n.loop-ui #actionPanel.active{border-left-color:var(--loop-glass-blue);box-shadow:none;background:#e8eeE5}\n.loop-ui #actionPanel :is(.stage-lines,#stageText){color:var(--loop-ink)}\n.loop-ui :is(.context-action-buttons,.side-panel) :is(.need-action,.pulse):not(#nextLoopButton.mz58-loop-progress){border-color:#a68850;background:#eee1ba;color:#664912;animation:none}\n/* Notes read like annotations in the book, with tint used only for a selection. */\n.loop-ui #desktopNotePanel{background:var(--loop-paper-raised);border-top:1px solid var(--loop-rule)}\n.loop-ui #desktopNotePanel h2{color:var(--loop-rubric)}\n.loop-ui .desktop-note-header{flex-wrap:wrap;gap:8px;margin-bottom:10px}\n.loop-ui .desktop-note-header-actions{gap:6px;flex-wrap:wrap}\n.loop-ui .desktop-note-header-actions button{font-size:12px}\n.loop-ui :is(.desktop-note-scope,.desktop-note-footer,.note-free-text-label){color:var(--loop-muted);font-weight:400;font-size:12px}\n.loop-ui :is(.side-panel,.report-panel) :is(.note-inference-section,.note-inference-row,.note-snapshot-section,.note-snapshot-item,.strategy-debug-card){background:transparent;border-color:var(--loop-rule);border-radius:2px;box-shadow:none}\n.loop-ui :is(.side-panel,.report-panel) :is(.note-inference-section h3,.note-snapshot-heading h3){background:#ebe6d9;color:var(--loop-ink);border-color:var(--loop-rule);font-weight:400}\n.loop-ui .side-panel :is(.note-inference-select,.note-inference-chip,.note-snapshot-view){background:var(--loop-paper-raised);color:var(--loop-ink);border-color:var(--loop-control);font-size:12px}\n.loop-ui .side-panel :is(.note-inference-chip.selected,.note-inference-chip.is-selected,.note-inference-chip[aria-pressed=\"true\"]){background:var(--loop-glass-blue-soft);color:#234b52;border-color:var(--loop-glass-blue)}\n.loop-ui .side-panel :is(.note-inference-row-heading strong,.note-snapshot-view strong){color:var(--loop-ink);font-size:12px;font-weight:400}\n.loop-ui .side-panel :is(.note-snapshot-view small,.note-inference-row small){color:var(--loop-muted)}\n.loop-ui #desktopNoteText{background:var(--loop-paper-raised);color:var(--loop-ink);border:1px solid var(--loop-control);border-radius:2px;font:14px/1.9 var(--loop-body-font);padding:10px;box-sizing:border-box;max-width:100%;caret-color:var(--loop-rubric)}\n.loop-ui :is(.side-panel,.report-panel) :is(input,textarea)::placeholder{color:var(--loop-muted);opacity:1}\n.loop-ui #desktopNoteText:focus{outline:2px solid var(--loop-glass-blue);outline-offset:2px;box-shadow:none}\n.loop-ui #desktopNoteCount{color:var(--loop-glass-blue);font-weight:400;font-variant-numeric:tabular-nums}\n.loop-ui #desktopNoteCount.near-limit{color:#795015}\n.loop-ui #desktopNoteStatus.error{color:#8c3449}\n/* Public record: dark pigment on pale vellum. Token categories keep their hue families. */\n.loop-ui #publicInfoPanel .meta>div{background:transparent;border:0;border-bottom:1px solid var(--loop-rule);border-radius:0;padding:8px 0}\n.loop-ui #publicInfoPanel .meta span{color:var(--loop-muted);font-size:12px}\n.loop-ui #publicInfoPanel .meta strong{color:var(--loop-ink);font:400 17px/1.6 var(--loop-title-font);font-variant-numeric:tabular-nums;overflow-wrap:anywhere}\n.loop-ui #publicInfoPanel .public-events-meta strong{font-size:13px}\n.loop-ui :is(.public-log-heading,.public-log-heading-actions,#publicLogPanel>.row){gap:6px;flex-wrap:wrap}\n.loop-ui #publicLog{scrollbar-color:#a59986 transparent;scrollbar-width:thin}\n.loop-ui .log-entry{background:transparent;color:var(--loop-ink);border:0;border-bottom:1px solid var(--loop-rule);border-radius:0;box-shadow:none;padding:12px 0;font:13px/1.85 var(--loop-body-font)}\n.loop-ui .log-entry strong{color:var(--loop-rubric);font-weight:400}\n.loop-ui :is(.report-panel,.side-panel){--log-phase-color:var(--loop-glass-blue)}\n.loop-ui :is(.report-panel,.side-panel) .phase-morning{--log-phase-color:#37645c}\n.loop-ui :is(.report-panel,.side-panel) .phase-cards{--log-phase-color:#74591f}\n.loop-ui :is(.report-panel,.side-panel) .phase-mastermind{--log-phase-color:#883c43}\n.loop-ui :is(.report-panel,.side-panel) .phase-protagonist{--log-phase-color:#325f68}\n.loop-ui :is(.report-panel,.side-panel) .phase-incident{--log-phase-color:#6b4e71}\n.loop-ui :is(.report-panel,.side-panel) .phase-night{--log-phase-color:#3b644c}\n.loop-ui :is(.report-panel,.side-panel) .phase-loop{--log-phase-color:#655f56}\n.loop-ui :is(.report-panel,.side-panel) .phase-final{--log-phase-color:#88334b}\n.loop-ui :is(.side-panel,.report-panel) :is(.public-log-group,.public-log-compact-group,.frame){background:transparent;border:1px solid var(--loop-rule);border-radius:2px;box-shadow:none}\n.loop-ui :is(.side-panel,.report-panel) .public-log-group-heading{background:#ebe6d9;border:0;border-left:2px solid var(--log-phase-color);color:var(--log-phase-color);font:400 13px/1.65 var(--loop-body-font)}\n.loop-ui :is(.side-panel,.report-panel) .public-log-dialog-entry{background:transparent;color:var(--loop-ink);border-color:var(--loop-rule);font:13px/1.85 var(--loop-body-font)}\n.loop-ui :is(.side-panel,.report-panel) .public-log-character{color:var(--loop-ink);font-weight:600}\n.loop-ui :is(.side-panel,.report-panel) .public-log-token.token-intrigue{color:#765818}\n.loop-ui :is(.side-panel,.report-panel) .public-log-token.token-paranoia{color:#6c497c}\n.loop-ui :is(.side-panel,.report-panel) .public-log-token.token-goodwill{color:#8a385b}\n.loop-ui :is(.side-panel,.report-panel) .frame-phase-title{background:var(--loop-glass-rose);color:var(--loop-rubric);border-color:#d0b4b8;font-weight:400}\n.loop-ui :is(.side-panel,.report-panel) :is(.pill,.pill.accent){background:var(--loop-glass-blue-soft);color:#234b52;border-color:#a3b7ae;border-radius:2px;font-weight:400;font-size:12px}\n/* Game containers are never transformed: fixed previews and native drawers must stay fixed. */\n@media(min-width:1001px){\n  .loop-ui>main{grid-template-columns:224px minmax(0,1fr) 280px!important;padding:4px 24px 40px!important;gap:20px!important;height:auto;overflow:visible}\n  .loop-ui .play-area{height:auto!important;max-height:none!important;overflow:visible;grid-template-rows:auto auto;align-self:start}\n  .loop-ui .board-section{flex:none}\n  .loop-ui #boardZoomShell{flex:none;height:auto;align-items:flex-start}\n  .loop-ui #handPanel{max-height:none;height:auto}\n  .loop-ui .side-panel,.loop-ui .report-panel{height:auto;max-height:calc(100dvh - 28px);align-self:start;overflow:auto}\n  .loop-ui .report-panel{top:16px}\n  .loop-ui.loop-focus>main{grid-template-columns:224px minmax(0,1fr)!important}\n  .loop-ui.loop-focus>main>.report-panel{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr 2fr}\n  .loop-ui.loop-focus .play-area{grid-column:2;grid-row:1}\n}\n@media(min-width:1650px){.loop-ui>main{grid-template-columns:240px minmax(0,1fr) 304px!important;gap:24px!important}.loop-ui.loop-focus>main{grid-template-columns:240px minmax(0,1fr)!important}}\n@media(min-width:1001px) and (max-width:1250px){\n  .loop-ui>main{grid-template-columns:216px minmax(0,1fr)!important;padding:4px 20px 40px!important}\n  .loop-ui>main>.report-panel{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr 2fr}\n  .loop-ui .play-area{padding:18px 20px 32px}\n}\n@media(max-width:1000px){\n  .loop-ui .loop-intro{padding:12px 16px 20px;min-height:80px;gap:12px}\n  .loop-title-ornament{width:40px;height:40px;flex-basis:40px}\n  .loop-ui .loop-intro h1{font-size:23px;letter-spacing:.04em}\n  .loop-ui .loop-intro p{font-size:12px;letter-spacing:0}\n  .loop-intro-actions{display:none}\n  .loop-ui>header{padding:8px 16px!important;gap:8px 16px}\n  .loop-ui .play-area{padding:12px 10px 28px}\n  .loop-ui #board{gap:12px}\n  .loop-ui .side-panel,.loop-ui .report-panel{background:var(--loop-paper);border:0;box-shadow:none}\n  .loop-ui .mobile-drawer-panel{background:var(--loop-paper)!important;color:var(--loop-ink)!important}\n  .loop-ui #handPanel.mobile-drawer-panel{background:#292328!important;color:var(--loop-night-ink)!important}\n  .loop-ui .phase-main>strong{font-size:12px}\n  .loop-ui :is(.side-panel,.report-panel) button{min-height:40px}\n}\n@media(max-width:600px){\n  .loop-ui .loop-intro h1{font-size:20px}.loop-title-ornament{width:36px;height:36px;flex-basis:36px}\n  .loop-ui .loop-header-actions button{padding:7px 10px;font-size:12px;min-height:40px}\n  .loop-ui>header>.toolbar{gap:14px}.loop-ui>header .nav{font-size:12px;min-height:36px}\n  .loop-ui .play-area{padding:8px 6px 26px}.loop-ui #board{gap:8px}\n  .loop-ui .phase-banner{margin-bottom:12px}.loop-ui .phase-main>strong{font-size:12px}\n  .loop-ui .loop-ambient{display:none}\n}\n.loop-restore{position:fixed;right:20px;bottom:20px;z-index:10029;display:flex;align-items:center;gap:10px;padding:10px 16px;border:1px solid #b79762;border-radius:3px;background:#231a29;color:#ebd9b1;font:14px var(--loop-body-font,serif);box-shadow:0 8px 30px #0005;cursor:pointer}\n.loop-restore svg{width:28px;height:28px}\n.loop-settings{--loop-ink:#332e2c;--loop-muted:#6a6057;width:min(480px,calc(100% - 32px));max-height:calc(100dvh - 48px);box-sizing:border-box;overflow:auto;border:1px solid #a17b45;border-radius:3px;padding:24px;background:#f4eddd;color:#332e2c;box-shadow:0 0 0 4px #332633,0 0 0 5px #af915c,0 20px 80px #0006;font:14px/1.7 var(--loop-body-font,serif)}\n.loop-settings::backdrop{background:#100e12bd}\n.loop-settings-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}\n.loop-settings h2{font:400 22px var(--loop-title-font,serif);color:#743c4d;margin:0}\n.loop-settings label{display:block;margin:16px 0 0;color:#4b3b3b}\n.loop-settings :is(input:not([type=checkbox]),textarea,select){display:block;box-sizing:border-box;width:100%;margin-top:8px;min-height:40px;border:1px solid #ad9d89;border-radius:2px;background:#fcf7ed;color:#332e2c;font:14px/1.6 var(--loop-body-font,serif);padding:9px}\n.loop-settings textarea{resize:vertical}\n.loop-settings input[type=checkbox]{accent-color:#743c4d;margin-right:8px}\n.loop-settings .loop-settings-help{font-size:12px;line-height:1.8;color:#6a6057;margin:14px 0}\n.loop-settings-buttons{display:flex;justify-content:space-between;gap:16px;margin-top:24px}\n.loop-settings button{min-height:40px;padding:8px 14px;border:1px solid #ad9d89;border-radius:2px;background:#fcf7ed;color:#663c45;font:14px var(--loop-body-font,serif);cursor:pointer}\n.loop-settings button:hover{border-color:#743c4d}\n.loop-settings button[type=submit]{background:#743c4d;color:#fff6e8;border-color:#743c4d}\n@keyframes loop-open-book{from{opacity:.7}to{opacity:1}}\n.loop-ui.loop-no-motion .play-area{animation:none}\n@media(prefers-reduced-motion:reduce){.loop-ui .play-area{animation:none}}\n\n/* ===== v3 refinement layers (appended) ===== */\n\n/* ---------- legibility.css ---------- */\n/* Reference-page legibility layer.\n   The installed Tsukushi cut on this machine is FOT-TsukuMinPro-L = Light, a display weight.\n   Light Mincho is beautiful at display sizes (28–40px) and fragile at 11–12px, especially at 1x DPR.\n   Rule: Tsukushi keeps headings / large text; anything under 13px switches to a gothic at 13px. */\n.loop-ui :is(\n  header .nav,\n  #musicPlayer,\n  .phase-banner-right > .phase-today-incident,\n  .action-card small,\n  .side-panel button,\n  .report-panel button,\n  .match-session-actions button,\n  .desktop-note-header-actions button,\n  .desktop-note-scope,\n  .desktop-note-footer,\n  .note-free-text-label,\n  .note-inference-row-heading strong,\n  #publicInfoPanel .meta span,\n  .loop-intro p,\n  .phase-main > strong,\n  .loop-settings-help,\n  .preview-log-time,\n  .public-log-group-heading,\n  .log-entry > strong\n) {\n  font-family: \"Microsoft YaHei UI\", \"Microsoft YaHei\", \"Noto Sans SC\", \"Yu Gothic UI\", sans-serif;\n  font-size: 13px;\n  line-height: 1.55;\n  letter-spacing: 0.01em;\n}\n\n/* keep buttons and chips on their existing geometry */\n.loop-ui :is(.side-panel button, .report-panel button, .match-session-actions button,\n  .desktop-note-header-actions button, header .nav) {\n  font-weight: 500;\n}\n\n/* ---------- interactions.css ---------- */\n/* GT interaction reskin — PRESENTATION ONLY.\n   Contract: this file may change colours, borders, shadows, backgrounds and type.\n   It must not change DOM structure, geometry (size/padding/position), handlers or game state.\n   It targets the game's own classes only; every element keeps its original box and behaviour. */\n\n/* character card lightbox (overlay > panel > title+close > card image) */\n.loop-ui .char-card-lightbox {\n  background:\n    radial-gradient(ellipse 70% 55% at 50% 42%, rgba(58, 42, 24, .52), rgba(8, 6, 4, .86) 72%),\n    rgba(8, 6, 4, .80);\n}\n\n.loop-ui .char-card-lightbox-panel {\n  background: linear-gradient(180deg, #f7f0df, #ecdfc4);\n  border-color: #a8802f;\n  box-shadow:\n    0 0 0 1px rgba(109, 79, 31, .55) inset,\n    0 0 0 5px rgba(244, 237, 221, .10),\n    0 26px 60px rgba(0, 0, 0, .60);\n}\n\n.loop-ui .char-card-lightbox-title {\n  color: #2b2018;\n  font-family: var(--loop-body-font);\n  letter-spacing: .08em;\n  border-bottom: 1px solid rgba(168, 128, 47, .45);\n}\n\n.loop-ui .char-card-lightbox-title button {\n  font-family: \"Microsoft YaHei UI\", \"Microsoft YaHei\", \"Noto Sans SC\", sans-serif;\n  color: #6e221c;\n  background: #fbf6e9;\n  border-color: #a8802f;\n}\n\n.loop-ui .char-card-lightbox-title button:hover {\n  background: #f3e6cb;\n  border-color: #8d2320;\n}\n\n.loop-ui .char-card-lightbox img {\n  border: 1px solid #b3925a;\n  box-shadow: 0 8px 22px rgba(0, 0, 0, .35);\n}\n\n/* hover / click card preview */\n.loop-ui .desktop-card-preview,\n.loop-ui .card-preview {\n  background: #f4eddd;\n  border-color: #a8802f;\n  box-shadow: 0 10px 26px rgba(0, 0, 0, .42), 0 0 0 1px rgba(168, 128, 47, .22) inset;\n  color: #2b2018;\n}\n\n.loop-ui .desktop-card-preview strong {\n  color: #2b2018;\n  font-family: var(--loop-body-font);\n}\n\n/* quick deduction options (\"快捷推理\") — buttons keep their own box, only paint changes */\n.loop-ui .quick-card-option button {\n  background: linear-gradient(180deg, #fbf5e6, #ecdfc2);\n  border-color: #a8802f;\n  color: #2b2018;\n  box-shadow: 0 2px 0 #cdb789, 0 6px 14px rgba(0, 0, 0, .16);\n}\n\n.loop-ui .quick-card-option button:hover:not(:disabled) {\n  border-color: #8d2320;\n  box-shadow: 0 0 0 2px rgba(141, 35, 32, .14), 0 8px 18px rgba(0, 0, 0, .20);\n}\n\n.loop-ui .quick-card-option button:disabled {\n  filter: grayscale(.65);\n}\n\n.loop-ui .quick-card-option strong {\n  color: #8d2320;\n  font-weight: 600;\n}\n\n.loop-ui .quick-card-option span { color: #4a3a26; }\n.loop-ui .quick-card-option small { color: #7b6446; }\n\n/* choice / utility dialogs — paint only */\n.loop-ui .choice-dialog,\n.loop-ui .utility-dialog {\n  background: #f4eddd;\n  color: #2b2018;\n  border-color: #a8802f;\n  box-shadow: 0 0 0 1px rgba(109, 79, 31, .40) inset, 0 26px 60px rgba(0, 0, 0, .58);\n}\n\n.loop-ui .choice-dialog::backdrop,\n.loop-ui .utility-dialog::backdrop {\n  background: rgba(10, 7, 4, .68);\n}\n\n.loop-ui .choice-dialog h2,\n.loop-ui .utility-dialog h2 {\n  color: #6e221c;\n  font-family: var(--loop-body-font);\n}\n\n.loop-ui .choice-dialog button,\n.loop-ui .utility-dialog button {\n  color: #4a3a26;\n  background: #fbf6e9;\n  border-color: #a8802f;\n}\n\n.loop-ui .choice-dialog button:hover,\n.loop-ui .utility-dialog button:hover {\n  border-color: #8d2320;\n  color: #6e221c;\n}\n\n/* ---------- quick-note.css ---------- */\n/* GT · quick reasoning modal — recoded UI for the illuminated-codex brief.\n   Structure and behaviour stay the game's own (notes.js builds it, handlers untouched);\n   everything painted below is presentation: parchment leaves, rubric band, gilt rules,\n   wax-seal chips, vellum note area. */\n\n/* ---------- overlay: candlelit stone behind the leaf ---------- */\n.loop-ui .choice-dialog-overlay.character-quick-note-overlay {\n  background:\n    radial-gradient(ellipse 70% 55% at 50% 38%, rgba(70, 48, 24, .55), rgba(8, 6, 4, .90) 70%),\n    radial-gradient(circle at 50% 100%, rgba(120, 82, 34, .18), transparent 55%),\n    #0b0806;\n  backdrop-filter: blur(4px) saturate(.9);\n}\n\n/* ---------- the leaf ---------- */\n.loop-ui .character-quick-note-dialog {\n  position: relative;\n  background:\n    linear-gradient(180deg, rgba(255, 252, 244, .97), rgba(238, 226, 201, .99)),\n    #f4eddd;\n  border: 2px solid #a8802f;\n  border-radius: 3px;\n  color: #2b2018;\n  box-shadow:\n    0 0 0 1px rgba(109, 79, 31, .55) inset,\n    0 0 0 6px rgba(244, 237, 221, .08),\n    0 30px 80px rgba(0, 0, 0, .65);\n}\n\n/* gilt inner rule, like the ruled border of an illuminated page */\n.loop-ui .character-quick-note-dialog::before {\n  content: \"\";\n  position: absolute;\n  inset: 7px;\n  border: 1px solid rgba(168, 128, 47, .38);\n  pointer-events: none;\n}\n\n/* ---------- rubric band header ---------- */\n.loop-ui .character-quick-note-header {\n  position: relative;\n  background:\n    linear-gradient(180deg, #33161a, #24100f 70%),\n    #2b1418;\n  border-bottom: 1px solid rgba(201, 163, 90, .55);\n  box-shadow: 0 0 0 1px rgba(201, 163, 90, .18) inset;\n}\n\n.loop-ui .character-quick-note-header::after {\n  content: \"\";\n  position: absolute;\n  left: 14px;\n  right: 14px;\n  bottom: 3px;\n  height: 1px;\n  background: linear-gradient(90deg, transparent, rgba(201, 163, 90, .55), transparent);\n}\n\n.loop-ui .character-quick-note-header span {\n  color: #c9a35a;\n  letter-spacing: .20em;\n  font-family: \"Microsoft YaHei UI\", \"Microsoft YaHei\", \"Noto Sans SC\", sans-serif;\n  font-size: 11px;\n}\n\n.loop-ui .character-quick-note-header h2 {\n  color: #f5ead6;\n  font-family: var(--loop-body-font);\n  letter-spacing: .05em;\n}\n\n.loop-ui .character-quick-note-dialog .dialog-icon-button {\n  color: #f2e7ce;\n  background: #3a1d1c;\n  border: 1px solid #a8802f;\n  border-radius: 2px;\n}\n\n.loop-ui .character-quick-note-dialog .dialog-icon-button:hover {\n  background: #4a2422;\n  border-color: #c9a35a;\n}\n\n/* ---------- guide line ---------- */\n.loop-ui .character-quick-note-guide {\n  color: #6a5a44;\n  font-family: \"Microsoft YaHei UI\", \"Microsoft YaHei\", \"Noto Sans SC\", sans-serif;\n  font-size: 12.5px;\n}\n\n/* ---------- sections as vellum panels ---------- */\n.loop-ui .character-quick-note-section {\n  background: rgba(255, 252, 244, .50);\n  border: 1px solid rgba(168, 128, 47, .35);\n  border-radius: 2px;\n}\n\n.loop-ui .character-quick-note-section h3 {\n  color: #8d2320;\n  font-family: var(--loop-body-font);\n  letter-spacing: .12em;\n}\n\n/* ---------- chips: wax-seal states ---------- */\n.loop-ui .character-quick-note-choice {\n  background: #fbf6e9;\n  border: 1px solid #b3925a;\n  border-radius: 3px;\n  color: #2b2018;\n  font-family: \"Microsoft YaHei UI\", \"Microsoft YaHei\", \"Noto Sans SC\", sans-serif;\n  box-shadow: 0 1px 0 rgba(109, 79, 31, .25);\n}\n\n.loop-ui .character-quick-note-choice:hover,\n.loop-ui .character-quick-note-choice:focus-visible {\n  border-color: #8d2320;\n  box-shadow: 0 0 0 2px rgba(141, 35, 32, .14);\n}\n\n.loop-ui .character-quick-note-choice.is-possible {\n  border-color: #3f6b52;\n  background: #e9efe2;\n  color: #23422f;\n}\n\n.loop-ui .character-quick-note-choice.is-excluded {\n  border-color: #8d2320;\n  background: #f4e1de;\n  color: #6e1f1a;\n}\n\n.loop-ui .character-quick-note-choice.is-suspected {\n  border-color: #9a7423;\n  background: #f8eed7;\n  color: #6d4f14;\n}\n\n.loop-ui .character-quick-note-choice-mark {\n  color: inherit;\n}\n\n/* ---------- vellum note area ---------- */\n.loop-ui .character-quick-note-text-section textarea {\n  background: linear-gradient(180deg, #fffdf7, #f6eeda);\n  border: 1px solid #b3925a;\n  color: #2b2018;\n  font-family: var(--loop-body-font);\n}\n\n.loop-ui .character-quick-note-text-section textarea::placeholder {\n  color: #8a7a62;\n}\n\n.loop-ui .character-quick-note-text-heading > span {\n  color: #7b6446;\n  font-family: \"Microsoft YaHei UI\", \"Microsoft YaHei\", \"Noto Sans SC\", sans-serif;\n}\n\n/* ---------- footer ---------- */\n.loop-ui .character-quick-note-actions {\n  border-top: 1px solid rgba(168, 128, 47, .35);\n  padding-top: 10px;\n}\n\n.loop-ui .character-quick-note-actions > span {\n  color: #7b6446;\n}\n\n.loop-ui .character-quick-note-dialog .button {\n  color: #4a3a26;\n  background: #fbf6e9;\n  border: 1px solid #a8802f;\n  border-radius: 2px;\n}\n\n.loop-ui .character-quick-note-dialog .button.primary {\n  color: #f7f0df;\n  background: linear-gradient(180deg, #7a2a24, #5e1a24);\n  border-color: #8d2320;\n  box-shadow: 0 1px 0 rgba(0, 0, 0, .35), 0 0 0 1px rgba(201, 163, 90, .25) inset;\n}\n\n.loop-ui .character-quick-note-dialog .button:hover {\n  border-color: #8d2320;\n  color: #6e221c;\n}\n\n.loop-ui .character-quick-note-dialog .button.primary:hover {\n  color: #fff6e8;\n}\n\n/* ---------- panels.css ---------- */\n/* GT · dialog & panel layer — every click-opened surface in the game:\n   对局笔记 / 已用轮限牌 / 规则QA / 设置 / 模组详情 / 公开信息·日志 / 快照 / 角色池 …\n   Paint only: no geometry, display or position overrides. */\n\n/* ---------- scrim behind every dialog ---------- */\n.loop-ui .choice-dialog-overlay {\n  background:\n    radial-gradient(ellipse 70% 55% at 50% 40%, rgba(70, 48, 24, .50), rgba(8, 6, 4, .88) 72%),\n    rgba(8, 6, 4, .82);\n  backdrop-filter: blur(3px) saturate(.92);\n}\n\n/* ---------- dialog body ---------- */\n.loop-ui .choice-dialog {\n  background: linear-gradient(180deg, #f8f1e0, #ecdfc4), #f4eddd;\n  border: 2px solid #a8802f;\n  border-radius: 3px;\n  color: #2b2018;\n  box-shadow:\n    0 0 0 1px rgba(109, 79, 31, .50) inset,\n    0 0 0 5px rgba(244, 237, 221, .08),\n    0 28px 70px rgba(0, 0, 0, .62);\n}\n\n.loop-ui .choice-dialog :is(h1, h2, h3, h4) {\n  color: #6e221c;\n  font-family: var(--loop-body-font);\n  letter-spacing: .04em;\n}\n\n.loop-ui .choice-dialog h2 {\n  border-bottom: 1px solid rgba(168, 128, 47, .40);\n  padding-bottom: 8px;\n}\n\n.loop-ui .choice-dialog :is(p, li, label, span, small) {\n  color: #4a3a26;\n}\n\n.loop-ui .choice-dialog :is(strong, b) {\n  color: #2b2018;\n}\n\n.loop-ui .choice-dialog .empty {\n  color: #7b6446;\n}\n\n.loop-ui .choice-dialog :is(input, select, textarea) {\n  background: #fffdf7;\n  border: 1px solid #b3925a;\n  border-radius: 2px;\n  color: #2b2018;\n}\n\n.loop-ui .choice-dialog :is(input, textarea)::placeholder {\n  color: #8a7a62;\n}\n\n.loop-ui .choice-dialog :is(input, select, textarea):focus {\n  border-color: #8d2320;\n  outline: 2px solid rgba(141, 35, 32, .15);\n}\n\n.loop-ui .choice-dialog button,\n.loop-ui .choice-dialog .button {\n  color: #4a3a26;\n  background: linear-gradient(180deg, #fbf6e9, #f2e6cc);\n  border: 1px solid #a8802f;\n  border-radius: 2px;\n}\n\n.loop-ui .choice-dialog button:hover,\n.loop-ui .choice-dialog .button:hover {\n  border-color: #8d2320;\n  color: #6e221c;\n}\n\n.loop-ui .choice-dialog .button.primary {\n  color: #f7f0df;\n  background: linear-gradient(180deg, #7a2a24, #5e1a24);\n  border-color: #8d2320;\n}\n\n.loop-ui .dialog-icon-button {\n  color: #6e221c;\n  background: #fbf6e9;\n  border: 1px solid #a8802f;\n  border-radius: 2px;\n}\n\n/* ---------- 对局笔记 ---------- */\n.loop-ui .note-dialog {\n  background: linear-gradient(180deg, #fbf5e7, #eee0c4), #f4eddd;\n}\n\n.loop-ui .note-dialog .note-dialog-header {\n  border-bottom: 1px solid rgba(168, 128, 47, .40);\n}\n\n.loop-ui .note-dialog .note-dialog-header h2 {\n  border-bottom: 0;\n}\n\n.loop-ui .note-dialog .note-table-launch-button {\n  background: linear-gradient(180deg, #7a2a24, #5e1a24);\n  border: 1px solid #8d2320;\n  color: #f7f0df;\n  border-radius: 2px;\n}\n\n.loop-ui .note-dialog .note-table-new-badge {\n  background: #c9a35a;\n  color: #2b1610;\n}\n\n.loop-ui .note-dialog .note-storage-scope {\n  color: #7b6446;\n  border-color: rgba(168, 128, 47, .45);\n}\n\n.loop-ui .note-dialog .note-workspace {\n  background: rgba(255, 252, 244, .45);\n  border: 1px solid rgba(168, 128, 47, .30);\n  border-radius: 2px;\n}\n\n.loop-ui .note-dialog .note-textarea {\n  background: linear-gradient(180deg, #fffdf7, #f6eeda);\n  border: 1px solid #b3925a;\n  color: #2b2018;\n  font-family: var(--loop-body-font);\n}\n\n.loop-ui .note-dialog .note-footer {\n  color: #7b6446;\n  border-top: 1px solid rgba(168, 128, 47, .35);\n}\n\n.loop-ui .note-dialog .note-snapshot-heading h3 {\n  color: #8d2320;\n}\n\n.loop-ui .note-dialog .tiny-link-button {\n  color: #6e221c;\n  border-bottom: 1px solid rgba(141, 35, 32, .45);\n}\n\n.loop-ui .note-dialog .note-snapshot-list > * {\n  background: #fbf6e9;\n  border: 1px solid rgba(168, 128, 47, .40);\n  border-radius: 2px;\n  color: #4a3a26;\n}\n\n.loop-ui .note-dialog .note-inference-section {\n  background: #f7efdd;\n  border: 1px solid rgba(168, 128, 47, .40);\n  border-radius: 2px;\n}\n\n.loop-ui .note-dialog .note-inference-section h3 {\n  color: #8d2320;\n}\n\n.loop-ui .note-dialog .note-inference-chip,\n.loop-ui .note-dialog .note-inference-select {\n  background: #fbf6e9;\n  border: 1px solid #b3925a;\n  color: #2b2018;\n}\n\n.loop-ui .note-dialog .note-quick-actions .button {\n  background: #f7efdd;\n  border-color: rgba(168, 128, 47, .55);\n}\n\n/* ---------- 已用轮限牌 ---------- */\n.loop-ui .loop-limit-dialog {\n  background: linear-gradient(180deg, #f8f1e0, #ecdfc4), #f4eddd;\n}\n\n.loop-ui .loop-limit-dialog .loop-limit-list {\n  border-top: 1px solid rgba(168, 128, 47, .35);\n}\n\n.loop-ui .loop-limit-dialog .loop-limit-list > * {\n  background: #fbf6e9;\n  border: 1px solid rgba(168, 128, 47, .40);\n  border-radius: 2px;\n  color: #4a3a26;\n}\n\n.loop-ui .loop-limit-dialog .loop-limit-list .empty {\n  background: transparent;\n  border: 0;\n  color: #7b6446;\n}\n\n/* ---------- settings / QA / module / public panels ---------- */\n.loop-ui .settings-dialog,\n.loop-ui .qa-dialog,\n.loop-ui .module-sheet-dialog,\n.loop-ui .public-info-dialog,\n.loop-ui .public-log-dialog {\n  background: linear-gradient(180deg, #f8f1e0, #ecdfc4), #f4eddd;\n}\n\n.loop-ui .public-info-dialog h3,\n.loop-ui .public-log-dialog h3 {\n  color: #8d2320;\n}\n\n/* ---------- 对局笔记 side panel: give it height instead of clipping the workspace ---------- */\n.loop-ui .desktop-note-panel {\n  min-height: 420px;\n}\n\n.loop-ui .desktop-note-panel .desktop-note-workspace {\n  min-height: 260px;\n}\n\n.loop-ui .desktop-note-panel .note-snapshot-section {\n  margin-top: 8px;\n}\n\n/* dialog variant: keep the scroll area generous so all characters are visible */\n.loop-ui .note-dialog .note-workspace {\n  max-height: min(62vh, 620px);\n}\n\n/* ---------- proportions.css ---------- */\n/* Reference proportions fix.\n   The fixture carries the engine's small-preview values (--loc-char-width: 75px/60px) and a\n   generous 26px padding inside .chars; on the live board a card is ~22% of the location width.\n   Enlarge the cards and reclaim the grid's padding so two rows still fit the panel. */\n.loop-ui .location .chars {\n  inset: 6px;\n  padding-top: 2px;\n  padding-right: 44px;\n  align-content: space-evenly;\n}\n\n.loop-ui .location {\n  --loc-char-width: 94px !important;\n  --loc-char-gap: 10px !important;\n}\n\n@media (max-width: 1000px) {\n  .loop-ui .location {\n    --loc-char-width: 64px !important;\n    --loc-char-gap: 8px !important;\n  }\n  .loop-ui .location .chars {\n    inset: 4px;\n    padding-top: 4px;\n    padding-right: 26px;\n  }\n}\n\n/* Sidebar columns: the base shell squeezes controls/report to 224/280px, which is narrower than the\n   game's own layout (min 220–300 / 280–360) and clips the 对局笔记 panel. Restore the original widths. */\n@media (min-width: 1001px) {\n  .loop-ui > main {\n    grid-template-columns: 280px minmax(0, 1fr) 320px !important;\n  }\n  .loop-ui.loop-focus > main {\n    grid-template-columns: 280px minmax(0, 1fr) !important;\n  }\n}\n\n@media (min-width: 1650px) {\n  .loop-ui > main {\n    grid-template-columns: 300px minmax(0, 1fr) 360px !important;\n  }\n  .loop-ui.loop-focus > main {\n    grid-template-columns: 300px minmax(0, 1fr) !important;\n  }\n}\n\n/* ===== v3.1 candlelit vellum theme =====\n   Direction: an illuminated manuscript read by candlelight in a stone church at dusk.\n   One warm neutral ramp (umber → vellum → ink), one accent pair (aged oxblood + muted gold),\n   desaturated stained-glass tints as atmosphere only. No pure white, no saturated red,\n   no hard black shadows. */\n\nbody.loop-ui {\n  --loop-ink: #3b3027;\n  --loop-muted: #7a6a55;\n  --loop-rubric: #6f3a3d;\n  --loop-gold: #a4874f;\n  --loop-paper: #e8dbc2;\n  --loop-paper-raised: #efe4cc;\n  --loop-rule: #c9b795;\n  --loop-control: #a89980;\n  --loop-glass-blue: #3f5a66;\n  --loop-glass-blue-soft: #dfe8e6;\n  --loop-glass-teal: #415a4e;\n  --loop-glass-rose: #e9dfd8;\n  --loop-night: #1b1410;\n  --loop-night-raised: #261c15;\n  --loop-night-ink: #e2d4bb;\n  --loop-night-muted: #b3a184;\n\n  background:\n    radial-gradient(1200px 700px at 50% -8%, rgba(96, 68, 40, .38), transparent 62%),\n    radial-gradient(900px 620px at 8% 106%, rgba(63, 90, 102, .16), transparent 66%),\n    radial-gradient(900px 620px at 92% 106%, rgba(111, 58, 61, .14), transparent 66%),\n    #1b1410;\n  color: var(--loop-night-ink);\n}\n\n/* darker, warmer chrome */\n.loop-ui > header {\n  background: linear-gradient(180deg, #241a13, #1c150f) !important;\n  border-bottom: 1px solid rgba(164, 135, 79, .22) !important;\n}\n.loop-ui > header .nav { color: #b3a184; }\n.loop-ui > header .nav:hover { color: #eadcc4; }\n\n/* the open book: softer page, gilded hairline instead of hard stacked edges */\n.loop-ui .play-area {\n  background:\n    radial-gradient(420px 260px at 0% 0%, rgba(63, 90, 102, .10), transparent 60%),\n    radial-gradient(420px 260px at 100% 0%, rgba(111, 58, 61, .09), transparent 60%),\n    linear-gradient(90deg,\n      transparent calc(var(--loop-spine, 50%) - 28px),\n      rgba(138, 116, 84, .10) calc(var(--loop-spine, 50%) - 10px),\n      rgba(128, 99, 66, .26) var(--loop-spine, 50%),\n      rgba(138, 116, 84, .10) calc(var(--loop-spine, 50%) + 10px),\n      transparent calc(var(--loop-spine, 50%) + 28px)),\n    radial-gradient(120% 90% at 50% 0%, #f2e8d3, #e8dbc2 58%, #e0d1b3);\n  border-color: rgba(164, 135, 79, .55);\n  box-shadow:\n    0 12px 34px rgba(12, 8, 6, .55),\n    0 0 0 1px rgba(164, 135, 79, .18) inset;\n}\n.loop-ui .play-area::before {\n  border-color: rgba(164, 135, 79, .30);\n}\n\n/* side panels: quieter vellum, no glare */\n.loop-ui .side-panel,\n.loop-ui .report-panel {\n  background: linear-gradient(180deg, #ece1c9, #e3d5ba);\n  border-color: rgba(164, 135, 79, .45);\n  box-shadow: 0 8px 22px rgba(12, 8, 6, .38);\n}\n\n/* dialogs: aged paper, muted rubric, soft edge */\n.loop-ui .choice-dialog-overlay {\n  background:\n    radial-gradient(ellipse 70% 55% at 50% 42%, rgba(64, 44, 26, .55), rgba(10, 7, 5, .86) 74%),\n    rgba(10, 7, 5, .80);\n  backdrop-filter: blur(3px) saturate(.9);\n}\n\n.loop-ui .choice-dialog {\n  background: linear-gradient(180deg, #ece0c8, #e2d3b7);\n  border: 1px solid rgba(164, 135, 79, .75);\n  color: var(--loop-ink);\n  box-shadow:\n    0 0 0 1px rgba(164, 135, 79, .22) inset,\n    0 24px 60px rgba(10, 7, 5, .58);\n}\n\n.loop-ui .choice-dialog :is(h1, h2, h3, h4) {\n  color: var(--loop-rubric);\n  border-bottom-color: rgba(164, 135, 79, .32);\n}\n\n.loop-ui .choice-dialog :is(p, li, label, span, small) { color: #4a3c31; }\n.loop-ui .choice-dialog :is(strong, b) { color: var(--loop-ink); }\n\n.loop-ui .choice-dialog :is(input, select, textarea) {\n  background: #f1e7d2;\n  border-color: #b29c74;\n  color: var(--loop-ink);\n}\n\n.loop-ui .choice-dialog :is(input, select, textarea):focus {\n  border-color: #84564f;\n  outline-color: rgba(132, 86, 79, .22);\n}\n\n.loop-ui .choice-dialog button,\n.loop-ui .choice-dialog .button {\n  background: linear-gradient(180deg, #efe4cc, #e6d8bd);\n  border-color: #b29c74;\n  color: #4a3c31;\n}\n\n.loop-ui .choice-dialog button:hover,\n.loop-ui .choice-dialog .button:hover {\n  border-color: #8a6a4a;\n  color: var(--loop-rubric);\n}\n\n.loop-ui .choice-dialog .button.primary {\n  background: linear-gradient(180deg, #75403f, #5d3132);\n  border-color: #6f3a3d;\n  color: #f0e4cc;\n}\n\n.loop-ui .dialog-icon-button {\n  background: #efe4cc;\n  border-color: #b29c74;\n  color: var(--loop-rubric);\n}\n\n/* 对局笔记 */\n.loop-ui .note-dialog { background: linear-gradient(180deg, #eee3cb, #e4d6ba); }\n.loop-ui .note-dialog .note-dialog-header { border-bottom-color: rgba(164, 135, 79, .32); }\n.loop-ui .note-dialog .note-table-launch-button {\n  background: linear-gradient(180deg, #75403f, #5d3132);\n  border-color: #6f3a3d;\n  color: #f0e4cc;\n}\n.loop-ui .note-dialog .note-table-new-badge {\n  background: #b08d55;\n  color: #2a1c14;\n}\n.loop-ui .note-dialog .note-storage-scope { color: #7a6a55; border-color: rgba(164, 135, 79, .35); }\n.loop-ui .note-dialog .note-workspace {\n  background: rgba(246, 238, 222, .55);\n  border-color: rgba(164, 135, 79, .28);\n}\n.loop-ui .note-dialog .note-textarea {\n  background: #f1e7d2;\n  border-color: #b29c74;\n  color: var(--loop-ink);\n}\n.loop-ui .note-dialog .note-footer {\n  color: #7a6a55;\n  border-top-color: rgba(164, 135, 79, .28);\n}\n.loop-ui .note-dialog .note-snapshot-heading h3,\n.loop-ui .note-dialog .note-inference-section h3 { color: var(--loop-rubric); }\n.loop-ui .note-dialog .tiny-link-button { color: var(--loop-rubric); border-bottom-color: rgba(111, 58, 61, .40); }\n.loop-ui .note-dialog .note-snapshot-list > * {\n  background: #f0e5cd;\n  border-color: rgba(164, 135, 79, .35);\n  color: #4a3c31;\n}\n.loop-ui .note-dialog .note-inference-section {\n  background: #efe4cc;\n  border-color: rgba(164, 135, 79, .32);\n}\n.loop-ui .note-dialog .note-inference-chip,\n.loop-ui .note-dialog .note-inference-select {\n  background: #f3ead6;\n  border-color: #b29c74;\n  color: var(--loop-ink);\n}\n.loop-ui .note-dialog .note-quick-actions .button {\n  background: #efe4cc;\n  border-color: rgba(164, 135, 79, .45);\n}\n\n/* 已用轮限牌 */\n.loop-ui .loop-limit-dialog { background: linear-gradient(180deg, #ece0c8, #e2d3b7); }\n.loop-ui .loop-limit-dialog .loop-limit-list { border-top-color: rgba(164, 135, 79, .30); }\n.loop-ui .loop-limit-dialog .loop-limit-list > * {\n  background: #f0e5cd;\n  border-color: rgba(164, 135, 79, .35);\n  color: #4a3c31;\n}\n.loop-ui .loop-limit-dialog .loop-limit-list .empty { color: #7a6a55; }\n\n/* 快捷推理 */\n.loop-ui .character-quick-note-dialog {\n  background: linear-gradient(180deg, #ece0c8, #e2d3b7);\n  border-color: rgba(164, 135, 79, .72);\n  box-shadow:\n    0 0 0 1px rgba(164, 135, 79, .22) inset,\n    0 24px 60px rgba(10, 7, 5, .58);\n}\n.loop-ui .character-quick-note-header {\n  background: linear-gradient(180deg, #5d3134, #4a272b);\n  color: #eadcc4;\n  border-bottom: 1px solid rgba(164, 135, 79, .35);\n}\n.loop-ui .character-quick-note-header h2 { color: #f0e4cc; }\n.loop-ui .character-quick-note-header span { color: #cbb48b; }\n.loop-ui .character-quick-note-section {\n  background: #efe4cc;\n  border-color: rgba(164, 135, 79, .32);\n}\n.loop-ui .character-quick-note-choice {\n  background: #f3ead6;\n  border-color: #b29c74;\n  color: var(--loop-ink);\n}\n.loop-ui .character-quick-note-choice.is-possible {\n  background: #e2e8dd;\n  border-color: #71856f;\n  color: #3c4a38;\n}\n.loop-ui .character-quick-note-choice.is-excluded {\n  background: #eadfd8;\n  border-color: #9a7c72;\n  color: #5a4038;\n}\n.loop-ui .character-quick-note-choice.is-suspected {\n  background: #f0e4c9;\n  border-color: #a4874f;\n  color: #5d4a28;\n}\n.loop-ui .character-quick-note-text-section textarea {\n  background: #f3ead6;\n  border-color: #b29c74;\n  color: var(--loop-ink);\n}\n\n/* 公开信息 / 日志 / 特殊规则: keep hierarchy, drop the hard dark bands */\n.loop-ui .public-log-group-heading {\n  background: #3f2d22;\n  color: #e4d6bd;\n}\n.loop-ui .public-info-dialog,\n.loop-ui .public-log-dialog,\n.loop-ui .settings-dialog,\n.loop-ui .qa-dialog,\n.loop-ui .module-sheet-dialog {\n  background: linear-gradient(180deg, #ece0c8, #e2d3b7);\n}\n\n/* ===== v3.1.1 card-open scrim: dim the board, never black it out ===== */\n.loop-ui .choice-dialog-overlay.character-quick-note-overlay {\n  background:\n    radial-gradient(ellipse 80% 70% at 50% 40%, rgba(40, 28, 16, .18), rgba(16, 11, 7, .42) 76%),\n    rgba(16, 11, 7, .28);\n  backdrop-filter: blur(1px) saturate(.96);\n}\n\n.loop-ui .char-card-lightbox {\n  background:\n    radial-gradient(ellipse 80% 70% at 50% 40%, rgba(40, 28, 16, .16), rgba(16, 11, 7, .38) 76%),\n    rgba(16, 11, 7, .32);\n}\n\n/* ===== v3.2 侧栏「对局笔记」排版修复 =====\n   症状：笔记表/保存快照按钮浮在标题上方并与标题重叠、引导文案是刺眼的青色、\n   下拉被裁切、面板底部出现内滚动条与截断。\n   做法：标题独占一行，动作收成右侧小工具；引导文案降为暖灰；\n   工作区改为纵向流，文本框给足高度；底部计数与状态一行对齐。 */\n\n.loop-ui .desktop-note-panel {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  padding: 14px 14px 12px;\n}\n\n.loop-ui .desktop-note-panel .desktop-note-header {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n  margin: 0;\n}\n\n.loop-ui .desktop-note-panel .desktop-note-header h2 {\n  flex: 0 0 auto;\n  margin: 0;\n  font-size: 17px;\n  letter-spacing: .05em;\n}\n\n.loop-ui .desktop-note-panel .desktop-note-header-actions {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 6px;\n  margin-left: auto;\n}\n\n.loop-ui .desktop-note-panel .note-table-launch-button-compact {\n  padding: 4px 9px;\n  font-size: 12px;\n  white-space: nowrap;\n}\n\n.loop-ui .desktop-note-panel .tiny-link-button {\n  padding: 3px 7px;\n  font-size: 12px;\n  white-space: nowrap;\n}\n\n.loop-ui .desktop-note-panel .character-note-entry-guide {\n  margin: 0;\n  color: var(--loop-muted);\n  font-size: 12.5px;\n  line-height: 1.55;\n}\n\n.loop-ui .desktop-note-panel .desktop-note-scope {\n  color: var(--loop-muted);\n}\n\n.loop-ui .desktop-note-panel .desktop-note-workspace {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  min-height: 0;\n}\n\n.loop-ui .desktop-note-panel .note-inference-board {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.loop-ui .desktop-note-panel .note-inference-row {\n  padding: 8px 9px;\n}\n\n.loop-ui .desktop-note-panel .note-inference-row-heading {\n  grid-template-columns: minmax(64px, .8fr) minmax(96px, 1.2fr);\n  gap: 6px;\n}\n\n.loop-ui .desktop-note-panel .note-snapshot-section {\n  margin: 0;\n}\n\n.loop-ui .desktop-note-panel .note-free-text-label {\n  margin: 2px 0 0;\n  color: var(--loop-muted);\n  font-size: 12px;\n}\n\n.loop-ui .desktop-note-panel .desktop-note-textarea {\n  min-height: 116px;\n  padding: 8px 10px;\n  background: #f3ead6;\n  border: 1px solid #b29c74;\n  border-radius: 2px;\n  color: var(--loop-ink);\n  font-size: 13px;\n  line-height: 1.62;\n  resize: vertical;\n}\n\n.loop-ui .desktop-note-panel .desktop-note-footer {\n  display: flex;\n  justify-content: space-between;\n  gap: 10px;\n  padding-top: 7px;\n  border-top: 1px solid rgba(164, 135, 79, .30);\n  color: var(--loop-muted);\n  font-size: 12px;\n}\n\n/* 侧栏再宽一点，给标题与两个工具按钮留出呼吸 */\n@media (min-width: 1001px) {\n  .loop-ui > main {\n    grid-template-columns: 300px minmax(0, 1fr) 320px !important;\n  }\n  .loop-ui.loop-focus > main {\n    grid-template-columns: 300px minmax(0, 1fr) !important;\n  }\n}\n\n@media (min-width: 1650px) {\n  .loop-ui > main {\n    grid-template-columns: 320px minmax(0, 1fr) 360px !important;\n  }\n}\n\n/* ===== v3.2.1 侧栏笔记：整块自然展开，不在面板内出现「裁切 + 内滚动条」===== */\n.loop-ui .side-panel.stack {\n  max-height: none !important;\n  overflow: visible !important;\n}\n\n.loop-ui .desktop-note-panel {\n  flex: 0 0 auto;\n}\n\n.loop-ui .desktop-note-panel .desktop-note-workspace {\n  flex: 0 0 auto;\n  max-height: none;\n  overflow: visible;\n}\n\n/* 标题与两个工具尽量同排；窄时整组换到下一行，绝不压住标题 */\n.loop-ui .desktop-note-panel .desktop-note-header {\n  gap: 6px;\n}\n\n.loop-ui .desktop-note-panel .desktop-note-header h2 {\n  font-size: 16px;\n}\n\n.loop-ui .desktop-note-panel .desktop-note-header-actions {\n  flex-wrap: nowrap;\n  gap: 5px;\n}\n\n.loop-ui .desktop-note-panel .note-table-launch-button-compact {\n  font-size: 11.5px;\n  padding: 3px 6px;\n}\n\n.loop-ui .desktop-note-panel .tiny-link-button {\n  font-size: 11.5px;\n  padding: 2px 6px;\n}\n\n/* ===== v3.2.2 侧栏不再有内滚动：面板拉长，交给页面滚动 =====\n   左栏（side-panel）与右栏（report-panel）都取消 max-height / overflow / sticky；\n   原本在面板里自滚的区域（公开日志、frame、特殊规则）也全部展开。 */\n@media (min-width: 1001px) {\n  .loop-ui .side-panel,\n  .loop-ui .report-panel {\n    max-height: none !important;\n    overflow: visible !important;\n    height: auto !important;\n    align-self: start !important;\n    position: static !important;\n  }\n}\n\n.loop-ui .special-rules-scroll,\n.loop-ui .report-panel #frames,\n.loop-ui .report-panel #publicLog {\n  max-height: none !important;\n  overflow: visible !important;\n  padding-right: 0;\n}\n\n.loop-ui .desktop-note-panel,\n.loop-ui .desktop-note-panel .desktop-note-workspace {\n  max-height: none !important;\n  overflow: visible !important;\n}\n\n/* ===== v3.2.3 「当前操作」与其它侧栏段落同级 =====\n   症状：action-panel 在左栏里带着自己的底色/边框，像套在里面的子 panel；\n   棋盘左侧还有一个黑色竖条（token-bank），像悬在页外的控件。\n   做法：action-panel 扁平化，只保留与兄弟段落一致的分隔线；\n   token-bank 改成书页边上的羊皮纸小签。 */\n\n.loop-ui .side-panel > #actionPanel,\n.loop-ui .side-panel > #actionPanel.action-panel {\n  background: transparent !important;\n  border: 0 !important;\n  border-bottom: 1px solid var(--loop-rule) !important;\n  border-radius: 0 !important;\n  box-shadow: none !important;\n  margin: 0 !important;\n  padding: 14px 16px !important;\n  position: relative;\n}\n\n.loop-ui .side-panel > #actionPanel > .row {\n  margin: 0 0 8px;\n  padding: 0;\n  background: transparent;\n  border: 0;\n}\n\n.loop-ui .side-panel > #actionPanel .status,\n.loop-ui .side-panel > #actionPanel #phasePrompt {\n  color: var(--loop-muted);\n}\n\n/* 棋盘左侧的 token bank：从黑色浮条改成贴在页边的羊皮纸小签 */\n.loop-ui .token-bank {\n  background: linear-gradient(180deg, #efe4cc, #e6d8bd) !important;\n  border: 1px solid rgba(164, 135, 79, .55) !important;\n  border-radius: 2px !important;\n  box-shadow: 0 6px 16px rgba(12, 8, 6, .35) !important;\n  left: -44px;\n}\n\n.loop-ui .token-bank span {\n  color: var(--loop-muted) !important;\n  letter-spacing: .02em;\n}\n\n.loop-ui .token-bank img {\n  filter: drop-shadow(0 1px 2px rgba(12, 8, 6, .35));\n}\n\n/* ===== v3.2.4 抽屉/窄屏也不出现「深底 + 深字」=====\n   窄屏或高缩放下，对局笔记等面板会被装进 .mobile-drawer-panel（原站深色底）。\n   GT 的浅色文字变量一旦落进深色抽屉，标签就消失了。这里把抽屉本身改成羊皮纸，\n   并给笔记面板一个显式纸底作为兜底。 */\n\n.loop-ui .desktop-note-panel {\n  background: var(--loop-paper);\n}\n\n@media (max-width: 1000px) {\n  .loop-ui .mobile-drawer-panel {\n    background: linear-gradient(180deg, #efe4cc, #e6d8bd) !important;\n    border: 1px solid rgba(164, 135, 79, .55) !important;\n    border-radius: 3px !important;\n    color: var(--loop-ink) !important;\n    box-shadow: 0 -10px 30px rgba(12, 8, 6, .45) !important;\n  }\n\n  .loop-ui .mobile-drawer-panel :is(h1, h2, h3, h4, strong, b, p, li, span, label, small) {\n    color: var(--loop-ink);\n  }\n\n  .loop-ui .mobile-drawer-panel :is(.status, .desktop-note-scope, .character-note-entry-guide, .meta, .empty) {\n    color: var(--loop-muted);\n  }\n\n  .loop-ui .mobile-drawer-panel :is(input, select, textarea) {\n    background: #f3ead6;\n    border-color: #b29c74;\n    color: var(--loop-ink);\n  }\n}\n\n/* ===== v3.2.5 笔记面板背景必须包住整个列表 =====\n   原站在桌面上给 .side-panel .desktop-note-panel 设了 flex:1 0 260px / min-height:260px，\n   列表是脚本加载后动态撑开的；面板被锁在 260px 时背景只画到 260px，后面的行就露在深色页面上。\n   这里把笔记面板强制改成内容高度，背景随内容一起长。 */\n\n.loop-ui .side-panel > #desktopNotePanel,\n.loop-ui .side-panel > .desktop-note-panel {\n  flex: 0 0 auto !important;\n  min-height: 0 !important;\n  height: auto !important;\n  max-height: none !important;\n  overflow: visible !important;\n  background: var(--loop-paper) !important;\n}\n\n.loop-ui .side-panel > #desktopNotePanel .desktop-note-workspace {\n  flex: 0 0 auto !important;\n  height: auto !important;\n  max-height: none !important;\n  overflow: visible !important;\n}\n\n/* 其它同级段落也统一按内容高度排，不再参与拉伸 */\n.loop-ui .side-panel > section {\n  flex: 0 0 auto !important;\n}\n"; document.head.append(style); })();
/* Presentation only. Original game elements, artwork and network calls stay owned by the game. */
(() => {
  'use strict';
  function mount() {
    if (document.getElementById('loop-ui-shell')) return true;
    const main = document.querySelector('body > main');
    const header = document.querySelector('body > header');
    const side = main?.querySelector('.side-panel');
    const play = main?.querySelector('.play-area');
    if (!main || !header || !side || !play || !document.getElementById('board')) return false;

    const storage = {
      get(key) { try { return localStorage.getItem(`loop-interface-mod.${key}`); } catch { return null; } },
      set(key, value) { try { localStorage.setItem(`loop-interface-mod.${key}`, value); } catch { /* Private browsing may disallow storage. */ } }
    };
    const create = (tag, cls, html) => {
      const el = document.createElement(tag);
      el.className = cls;
      if (html) el.innerHTML = html; // Only static mod-authored markup; user text is assigned with textContent.
      return el;
    };
    const originalTitle = header.querySelector('h1')?.textContent.trim() || document.title;
    const defaults = { title: originalTitle, subtitle: '', font: 'tsukushi', motion: true };
    const fonts = {
      tsukushi: '"Loop Tsukushi", "FOT-TsukuMin Pro L", "Tsukushi Mincho", "筑紫明朝", "Yu Mincho", "Noto Serif SC", "Noto Serif CJK SC", "SimSun", serif',
      song: '"Noto Serif SC", "Noto Serif CJK SC", "Source Han Serif SC", "Songti SC", "SimSun", serif',
      readable: '"Microsoft YaHei", "PingFang SC", system-ui, sans-serif'
    };
    let saved = {};
    try { saved = JSON.parse(storage.get('appearance') || '{}') || {}; } catch { /* Use defaults for malformed settings. */ }
    if (saved.font === 'manuscript') saved.font = 'tsukushi';
    let prefs = {
      title: typeof saved.title === 'string' && saved.title.trim() ? saved.title.slice(0, 80) : defaults.title,
      subtitle: typeof saved.subtitle === 'string' ? saved.subtitle.slice(0, 160) : '',
      font: Object.hasOwn(fonts, saved.font) ? saved.font : defaults.font,
      motion: saved.motion !== false
    };

    // Original vector ornament, drawn locally. No image/font downloads or asset substitutions.
    const petals = Array.from({length:12}, (_,i) => `<g transform="rotate(${i*30} 80 80)"><path d="M80 74Q53 52 80 12Q107 52 80 74Z" fill="${['#833c58','#344675','#35706c','#ae794b'][i%4]}" stroke="#d5b87b" stroke-width="1.2"/><path d="M80 67V24M66 48H94" stroke="#e1c893" stroke-width=".7" opacity=".7"/></g>`).join('');
    const rose = `<svg viewBox="0 0 160 160" aria-hidden="true"><circle cx="80" cy="80" r="77" fill="#292334" stroke="#ba9356" stroke-width="2"/><circle cx="80" cy="80" r="71" fill="none" stroke="#dac58e"/>${petals}<circle cx="80" cy="80" r="16" fill="#632c49" stroke="#d5b77f"/><path d="M80 67L84 76L93 80L84 84L80 93L76 84L67 80L76 76Z" fill="#ead8a9"/></svg>`;
    const lancet = `<svg viewBox="0 0 240 520" aria-hidden="true"><path d="M15 510V154Q15 77 120 10Q225 77 225 154V510Z" fill="#142a36" stroke="#af8c54" stroke-width="3"/><path d="M27 496V160Q27 88 120 26Q213 88 213 160V496Z" fill="#26314c" stroke="#a98e60"/><path d="M120 27L46 135L120 212L194 135Z" fill="#763b59" stroke="#b79a66"/><path d="M27 160L120 212L27 300ZM213 160L120 212L213 300Z" fill="#367477" stroke="#b79a66"/><path d="M27 300L120 212L213 300L120 391Z" fill="#724568" stroke="#b79a66"/><path d="M27 300L120 391L27 496ZM213 300L120 391L213 496Z" fill="#47548a" stroke="#b79a66"/><path d="M27 496L120 391L213 496Z" fill="#887145" stroke="#b79a66"/><path d="M120 27V496M27 300H213M64 496V178Q64 137 120 97Q176 137 176 178V496" fill="none" stroke="#c4a16b"/><circle cx="120" cy="118" r="28" fill="#30243e" stroke="#c4a16b"/><path d="M120 94L126 112L144 118L126 124L120 142L114 124L96 118L114 112Z" fill="#c5a46a"/></svg>`;
    const ambient = create('div', 'loop-ambient', `<div>${lancet}</div><div>${lancet}</div>`);
    ambient.setAttribute('aria-hidden','true');
    document.body.append(ambient);

    const actions = create('div', 'loop-header-actions', '<button type="button" data-loop-settings>题签与字体</button><button type="button" data-loop-original>原版界面</button>');
    header.append(actions);
    const shell = create('div', 'loop-intro', `<div class="loop-title-ornament">${rose}</div><div class="loop-intro-copy"><h1></h1><p hidden></p></div><div class="loop-intro-actions"><button type="button" data-loop-focus aria-pressed="false">放大版图</button></div>`);
    shell.id = 'loop-ui-shell';
    main.before(shell);
    const glass = create('div','loop-panel-glass',rose);
    glass.setAttribute('aria-hidden','true');
    side.querySelector('section')?.append(glass);
    const leaf = '<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M3 96V3H96M8 71V8H71M13 45V13H45" fill="none" stroke="#96743f" stroke-width=".8"/><path d="M7 61Q36 53 25 30Q15 12 33 13Q54 13 45 37Q36 60 61 62M14 16Q14 40 39 42Q62 42 62 15" fill="none" stroke="#ac864b" stroke-width="1.3"/><path d="M24 31Q6 28 15 16Q29 16 24 31Z" fill="#814757"/><path d="M39 42Q51 23 62 31Q62 45 39 42Z" fill="#3e6a66"/><path d="M47 56Q35 73 27 59Q32 47 47 56Z" fill="#b49456"/><circle cx="13" cy="13" r="4" fill="#b49355"/><circle cx="62" cy="62" r="2.5" fill="#8e465b"/></svg>';
    const margins = create('div','loop-book-margins',`<i>${leaf}</i><i>${leaf}</i><i>${leaf}</i><i>${leaf}</i><b></b>`);
    margins.setAttribute('aria-hidden','true');
    play.append(margins);
    // Keep the fold aligned with the actual map gap, including the game's variable-width counter.
    const alignFold = () => {
      if (!document.body.classList.contains('loop-ui')) return;
      const bookRect = play.getBoundingClientRect();
      const boardRect = document.getElementById('board')?.getBoundingClientRect();
      if (!bookRect.width || !boardRect?.width) return;
      const fold = `${Math.round((boardRect.left + boardRect.width / 2 - bookRect.left) * play.offsetWidth / bookRect.width)}px`;
      if (play.style.getPropertyValue('--loop-spine') !== fold) play.style.setProperty('--loop-spine',fold);
    };
    const layoutObserver = new ResizeObserver(alignFold);
    layoutObserver.observe(play);
    layoutObserver.observe(document.getElementById('board'));
    play.addEventListener('animationend', event => {
      if (event.target === play && event.animationName === 'loop-open-book') alignFold();
    });
    const restore = create('button', 'loop-restore', `${rose}<span>书卷界面</span>`);
    restore.type = 'button';
    restore.id = 'loop-ui-restore';
    document.body.append(restore);

    const dialog = create('dialog','loop-settings', `<form method="dialog"><div class="loop-settings-heading"><h2 id="loop-settings-title">题签与字体</h2><button type="button" data-loop-close aria-label="关闭">×</button></div><p class="loop-settings-help">书卷题签由你填写；留空标题将使用原站名称。副标题留空时不显示。</p><label>标题<input name="title" maxlength="80" autocomplete="off"></label><label>副标题<textarea name="subtitle" rows="2" maxlength="160"></textarea></label><label>字体<select name="font"><option value="tsukushi">筑紫明朝 · Tsukushi Mincho（优先）</option><option value="song">刊本 · 宋体</option><option value="readable">清晰阅读 · 黑体</option></select></label><label class="loop-motion-label"><input name="motion" type="checkbox">开卷动效</label><p class="loop-settings-help">优先使用本机的筑紫明朝，缺失时回退到本机字体。不会下载字体文件。题签仅保存在此浏览器。</p><div class="loop-settings-buttons"><button type="button" data-loop-reset>恢复默认</button><button type="submit" value="save">保存</button></div></form>`);
    dialog.setAttribute('aria-labelledby','loop-settings-title');
    document.body.append(dialog);
    const form = dialog.querySelector('form');
    const field = name => form.elements.namedItem(name);
    const paintPreferences = () => {
      shell.querySelector('h1').textContent = prefs.title;
      const subtitle = shell.querySelector('p');
      subtitle.textContent = prefs.subtitle;
      subtitle.hidden = !prefs.subtitle.trim();
      document.body.style.setProperty('--loop-title-font', fonts[prefs.font]);
      document.body.style.setProperty('--loop-body-font', fonts[prefs.font]);
      document.body.classList.toggle('loop-no-motion', !prefs.motion);
      document.body.classList.toggle('loop-readable', prefs.font === 'readable');
    };
    const fillSettings = () => {
      field('title').value = prefs.title;
      field('subtitle').value = prefs.subtitle;
      field('font').value = prefs.font;
      field('motion').checked = prefs.motion;
    };
    actions.querySelector('[data-loop-settings]').addEventListener('click', () => {
      fillSettings();
      dialog.showModal();
    });
    dialog.querySelector('[data-loop-close]').addEventListener('click', () => dialog.close());
    dialog.querySelector('[data-loop-reset]').addEventListener('click', () => {
      field('title').value = defaults.title;
      field('subtitle').value = defaults.subtitle;
      field('font').value = defaults.font;
      field('motion').checked = defaults.motion;
    });
    form.addEventListener('submit', event => {
      event.preventDefault();
      prefs = {title:field('title').value.trim().slice(0,80) || defaults.title, subtitle:field('subtitle').value.trim().slice(0,160), font:field('font').value, motion:field('motion').checked};
      storage.set('appearance', JSON.stringify(prefs));
      paintPreferences();
      dialog.close();
    });
    const focusButton = shell.querySelector('[data-loop-focus]');
    const setFocus = enabled => {
      document.body.classList.toggle('loop-focus', enabled);
      focusButton.setAttribute('aria-pressed',String(enabled));
      focusButton.textContent = enabled ? '恢复双栏' : '放大版图';
      window.dispatchEvent(new Event('resize'));
    };
    const apply = enabled => {
      document.body.classList.toggle('loop-ui', enabled);
      if (!enabled) { setFocus(false); dialog.close(); }
      restore.hidden = enabled;
      storage.set('enabled', enabled ? '1' : '0');
      if (enabled) requestAnimationFrame(alignFold);
      window.dispatchEvent(new Event('resize'));
    };
    actions.querySelector('[data-loop-original]').addEventListener('click', () => apply(false));
    restore.addEventListener('click', () => apply(true));
    focusButton.addEventListener('click', () => setFocus(!document.body.classList.contains('loop-focus')));
    document.addEventListener('keydown', event => {
      if (event.key === 'Escape' && !dialog.open && document.body.classList.contains('loop-focus')) setFocus(false);
    });
    paintPreferences();
    apply(storage.get('enabled') !== '0');
    return true;
  }
  // Some versions render the game shell after document_idle. Watch only until it exists.
  if (!mount()) {
    const observer = new MutationObserver(() => { if (mount()) observer.disconnect(); });
    observer.observe(document.documentElement, {childList:true, subtree:true});
    setTimeout(() => observer.disconnect(), 30000);
  }
})();
